// Данные достижений Stay Out — ПОЛНЫЙ список (304 шт.), взят со страницы
// so-wiki.ru/wiki/Достижения (сохранённая HTML-копия страницы, распаршена целиком).
//
// name/description — обычные описательные фразы (не выдуманные имена существ),
// поэтому переведены как самый обычный UI-текст. Внутри встречаются игровые
// монстры без официальной английской локализации (бес, бляк, брутор, ведун,
// верлиока, домовой, леший, драуг, репей, студень) — они не выдуманы заново,
// а либо переведены обычным словом (бес → fiend, ведун → warlock), либо, если
// это устоявшийся в англоязычной культуре фольклорный термин — транслитерированы
// (домовой → domovoi, леший → leshy, драуг → draug), либо, если это чисто
// выдуманное название без аналога — транслитерированы как есть (бляк → Blyak,
// брутор → Brutor, верлиока → Verlioka, репей → Repey, студень → Ooze).

export interface LocaleText { ru: string; en: string }

export interface Achievement {
  name: LocaleText;
  description: LocaleText;
  category: LocaleText;
  hidden: boolean;
  exp: number;
}

