// Все известные категории — используются для легенды/фильтра. Дедуп по ru-значению.
export const ACHIEVEMENT_CATEGORIES: LocaleText[] = (() => {
  const seen = new Set<string>();
  const out: LocaleText[] = [];
  for (const a of ACHIEVEMENTS) {
    if (!seen.has(a.category.ru)) { seen.add(a.category.ru); out.push(a.category); }
  }
  return out;
})();
